  // Computed properties
  computed: {
    totalTaskCount() {
      return this.tableData ? this.tableData.length : 0;
    },
    projectTaskCount() {
      return this.tableData.filter(task => task.task_source === "PROJECT_MANAGEMENT").length;
    },
    internalTaskCount() {
      return this.tableData.filter(task => task.task_source === "INTERNAL" || !task.task_source || task.task_source === "" || task.task_source !== "PROJECT_MANAGEMENT" && task.task_source !== "CHECKLIST").length;
    },
    checklistTaskCount() {
      return this.tableData.filter(task => task.task_source === "CHECKLIST").length;
    },
    sourceFilterOptionsWithCounts() {
      return [{
        text: "All Sources",
        value: "ALL",
        count: this.totalTaskCount
      }, {
        text: "Project",
        value: "PROJECT",
        count: this.projectTaskCount
      }, {
        text: "Task",
        value: "INTERNAL",
        count: this.internalTaskCount
      }, {
        text: "Checklist",
        value: "CHECKLIST",
        count: this.checklistTaskCount
      }];
    },
    filteredTableData() {
      let filtered = this.tableData;

      // Apply source filter
      if (this.selectedSourceFilter === "ALL") {
        filtered = this.tableData;
      } else if (this.selectedSourceFilter === "PROJECT") {
        filtered = this.tableData.filter(task => task.task_source === "PROJECT_MANAGEMENT");
      } else if (this.selectedSourceFilter === "INTERNAL") {
        filtered = this.tableData.filter(task => task.task_source === "INTERNAL" || !task.task_source || task.task_source === "" || task.task_source !== "PROJECT_MANAGEMENT" && task.task_source !== "CHECKLIST");
      } else if (this.selectedSourceFilter === "CHECKLIST") {
        filtered = this.tableData.filter(task => task.task_source === "CHECKLIST");
      }

      // Apply search filter if search term exists
      if (this.searchValue && this.searchValue.trim() !== "") {
        const searchTerm = this.searchValue.toLowerCase().trim();
        filtered = filtered.filter(task => {
          // Search in task name
          if (task.task_name && task.task_name.toLowerCase().includes(searchTerm)) {
            return true;
          }

          // Search in task description
          if (task.task_description && task.task_description.toLowerCase().includes(searchTerm)) {
            return true;
          }

          // Search in assigned by name
          if (task.task_assign_by_name && task.task_assign_by_name.toLowerCase().includes(searchTerm)) {
            return true;
          }

          // Search in task source (including project name for projects)
          if (task.task_source === "PROJECT_MANAGEMENT" && task.project_name) {
            if (task.project_name.toLowerCase().includes(searchTerm)) {
              return true;
            }
          }

          // Search in status
          if (task.task_progress_status && task.task_progress_status.toLowerCase().includes(searchTerm)) {
            return true;
          }

          // Search in formatted dates
          const assignedDate = this.fetch_value(task.task_created_on);
          if (assignedDate && assignedDate.toLowerCase().includes(searchTerm)) {
            return true;
          }
          const completionDate = this.fetch_org_format(task.task_completion_date);
          if (completionDate && completionDate.toLowerCase().includes(searchTerm)) {
            return true;
          }

          // Search in checklist-specific fields
          if (task.is_checklist) {
            if (task.checklist_data && task.checklist_data.master_checklist_name) {
              if (task.checklist_data.master_checklist_name.toLowerCase().includes(searchTerm)) {
                return true;
              }
            }
          }
          return false;
        });
      }
      return filtered;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      return this.filteredTableData.slice(start, start + this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Methods
  methods: {
    // Data fetching methods
    async list_my_tasks() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        // Fetch tasks
        let taskResult = await API.graphql(graphqlOperation(list_assign_task_or_completed, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            actions: "ASSIGN_TO_ME",
            limit: 500,
            nextToken: null,
            task_progress_status: this.selectedStatus === "ALL" ? null : this.selectedStatus
          }
        }));

        // Fetch checklists
        let checklistResult = await API.graphql(graphqlOperation(list_user_checklists, {
          input: {
            limit: 500,
            nextToken: null
          }
        }));
        this.tableLoading = false;
        this.tableData = [];

        // Process tasks
        var taskResponse = taskResult.data.list_assign_task_or_completed;
        this.masterData = taskResponse.details;

        // Process checklists
        var checklistResponse = JSON.parse(checklistResult.data.list_user_checklists);
        if (checklistResponse.Status === "SUCCESS") {
          this.checklistData = checklistResponse.data || [];
        } else {
          this.checklistData = [];
        }

        // Combine tasks and checklists
        const combinedData = this.combineTasksAndChecklists(this.masterData, this.checklistData);

        // Sort tasks in the specified order: overdue, upcoming, on hold, completed
        this.tableData = this.sortTasksByPriority(combinedData);

        // Set total items for pagination - use filtered data length
        this.totalItems = this.filteredTableData.length;

        // Emit initial filter counts
        this.emitFilterCounts();
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Filter methods
    filterTasks() {
      this.currentPage = 1;
      this.totalItems = this.filteredTableData.length;
      this.emitFilterCounts();
    },
    emitFilterCounts() {
      this.$emit("total-task-count", this.totalTaskCount);
      this.$emit("project-task-count", this.projectTaskCount);
      this.$emit("internal-task-count", this.internalTaskCount);
      this.$emit("checklist-task-count", this.checklistTaskCount);
      const activeFiltersCount = this.selectedSourceFilter !== "ALL" ? 1 : 0;
      this.$emit("active-filters-count", activeFiltersCount);
    },
    handleFilterChange() {
      this.currentPage = 1;
      this.filterTasks();
    },
    clearFilter() {
      this.selectedSourceFilter = "ALL";
      this.currentPage = 1;
      this.filterTasks();
      this.showFilterDrawer = false;
    },
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    applyFilter() {
      this.showFilterDrawer = false;
      this.currentPage = 1;
      this.filterTasks();
    },
    // Dialog management methods
    handleRowClick(item) {
      this.componentcheck = 1;
      this.rowInfo = item;
      this.assignToMeDialog = true;
    },
    updateStatus(item) {
      if (item.is_checklist == undefined) {
        this.handleRowClick(item);
      }
      if (item.is_checklist) {
        this.checklistDialogData = item.checklist_data;
        this.checklistDialog = true;
      } else {
        this.$emit("updateTaskStatus", item);
      }
    },
    handleChecklistProgressUpdate(updateData) {
      const checklistIndex = this.tableData.findIndex(item => item.task_id === updateData.checklistId);
      if (checklistIndex !== -1) {
        this.tableData[checklistIndex].completion_percentage = updateData.completionPercentage;
        this.tableData[checklistIndex].checklist_data.completion_percentage = updateData.completionPercentage;
        if (updateData.completionPercentage === 100) {
          this.tableData[checklistIndex].task_progress_status = "COMPLETED";
        } else if (updateData.completionPercentage > 0) {
          this.tableData[checklistIndex].task_progress_status = "INPROGRESS";
        }
      }
      this.$emit("checklistProgressUpdated", updateData);
    },
    // Pagination methods
    handle_pagination() {
      if (this.nextToken) {
        this.list_my_tasks();
      }
    },
    // Utility methods
    getdateformate(formatMap) {
      var check_date = "yyyy-MM-dd";
      return check_date.replace(/DD|MMM|YYYY|MM/gi, matched => formatMap[matched]);
    },
    formatedatedisplay(dateString) {
      if (dateString == "N/A") {
        return dateString;
      }
      const [year, month, day] = dateString.split("-");
      if (day == undefined) {
        return dateString;
      }
      const dayPadded = day.padStart(2, "0");
      const numericMonthPadded = month.padStart(2, "0");
      const fullMonthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const fullMonthName = fullMonthNames[parseInt(month, 10) - 1];
      const formatMap = {
        dd: dayPadded,
        MM: numericMonthPadded,
        yyyy: year,
        MMM: fullMonthName
      };
      return this.getdateformate(formatMap);
    },
    fetch_org_format(value) {
      if (value != undefined) {
        return formatdisplayDate(value);
      }
    },
    formatTimestampToDate(timestamp) {
      const date = new Date(timestamp);
      return date.toISOString().split("T")[0];
    },
    fetch_value(val) {
      return formatedatetime(val / 1000);
    },
    // Data processing methods
    combineTasksAndChecklists(tasks, checklists) {
      const checklistTasks = checklists.map(checklist => {
        const mappedTask = {
          task_id: checklist.checklist_id,
          task_name: checklist.checklist_name,
          task_description: checklist.master_checklist_name,
          task_source: "CHECKLIST",
          task_assign_by_name: checklist.checklist_created_by_name,
          task_created_on: checklist.checklist_created_on ? checklist.checklist_created_on * 1000 : Date.now(),
          task_completion_date: checklist.checklist_end_date ? checklist.checklist_end_date : this.formatTimestampToDate(checklist.checklist_created_on * 1000),
          task_progress_status: checklist.completion_percentage === 100 ? "COMPLETED" : "INPROGRESS",
          is_checklist: true,
          checklist_data: checklist,
          completion_percentage: checklist.completion_percentage || 0,
          checklist_visibility: checklist.checklist_visiblity,
          master_checklist_id: checklist.master_checklist_id,
          checklist_created_by: checklist.checklist_created_by
        };
        return mappedTask;
      });
      const combined = [...tasks, ...checklistTasks];
      return combined;
    },
    sortTasksByPriority(tasks) {
      const today = new Date().toISOString().split("T")[0];

      // Separate tasks into categories
      const overdueTasks = tasks.filter(task => task.task_completion_date && this.formatedatedisplay(task.task_completion_date) < today && task.task_progress_status === "INPROGRESS");
      const upcomingTasks = tasks.filter(task => task.task_completion_date && this.formatedatedisplay(task.task_completion_date) >= today && task.task_progress_status === "INPROGRESS");
      const onHoldTasks = tasks.filter(task => task.task_progress_status === "HOLD");
      const completedTasks = tasks.filter(task => task.task_progress_status === "COMPLETED");
      const otherTasks = tasks.filter(task => !overdueTasks.includes(task) && !upcomingTasks.includes(task) && !onHoldTasks.includes(task) && !completedTasks.includes(task));

      // Sort each category by completion date
      overdueTasks.sort((a, b) => new Date(a.task_completion_date) - new Date(b.task_completion_date));
      upcomingTasks.sort((a, b) => new Date(a.task_completion_date) - new Date(b.task_completion_date));
      onHoldTasks.sort((a, b) => new Date(b.task_completion_date) - new Date(a.task_completion_date));
      completedTasks.sort((a, b) => new Date(b.task_completion_date) - new Date(a.task_completion_date));

      // Combine all categories in the specified order
      const result = [...overdueTasks, ...upcomingTasks, ...onHoldTasks, ...completedTasks, ...otherTasks];
      return result;
    },
    // Styling methods
    getSourceColor(source) {
      if (source === "PROJECT_MANAGEMENT") {
        return "primary";
      } else if (source === "INTERNAL") {
        return "success";
      } else if (source === "CHECKLIST") {
        return "info";
      }
      return "grey";
    },
    getSourceIcon(source) {
      if (source === "PROJECT_MANAGEMENT") {
        return "mdi-briefcase";
      } else if (source === "INTERNAL") {
        return "mdi-apps";
      } else if (source === "CHECKLIST") {
        return "mdi-format-list-checks";
      }
      return "mdi-view-list";
    },
    getStatusColor(status) {
      if (status === "COMPLETED") {
        return "green";
      } else if (status === "INPROGRESS") {
        return "orange";
      } else if (status === "HOLD") {
        return "amber";
      } else if (status === "WITHDRAWN") {
        return "red";
      } else if (status === "WITHDRAW") {
        return "red";
      } else if (status === "ASSIGNED") {
        return "brown";
      }
      return "grey";
    },
    // Text formatting methods
    truncateTaskName(taskName) {
      if (!taskName) return "";
      const maxLength = 35;
      if (taskName.length > maxLength) {
        return taskName.slice(0, maxLength) + "...";
      }
      return taskName;
    },
    smartTruncateTaskName(taskName) {
      if (!taskName) return "";
      const maxLength = 40;
      if (taskName.length <= maxLength) {
        return taskName;
      }
      const truncated = taskName.slice(0, maxLength);
      const lastSpaceIndex = truncated.lastIndexOf(" ");
      if (lastSpaceIndex > maxLength * 0.7) {
        return truncated.slice(0, lastSpaceIndex) + "...";
      }
      return truncated + "...";
    },
    getActiveFilterCount() {
      return this.sourceFilterOptionsWithCounts.filter(option => option.value === this.selectedSourceFilter).length;
    },
    getFilterLabel(value) {
      const labels = {
        ALL: "All Tasks",
        CHECKLIST: "Checklist",
        PROJECT: "Projects",
        INTERNAL: "My Tasks"
      };
      return labels[value] || "All Tasks";
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.assignToMeDialog = false;
      this.list_my_tasks();
    }
  }
